def icon(name: str) -> Markup:
    """SVG آیکون خطی استاندارد — نام نامعتبر به آیکون پیش‌فرض برمی‌گردد."""
    return Markup(ICONS.get(name or "", ICONS[DEFAULT_ICON]))
